import { href, value } from './view-context.js';
import { workflows, reportDigest, permittedReport } from './workflow-model.js';
import { body, heading, form, checks, action } from './workflow-ui.js';
import { field, link, button, panel, table, statusBadge, notice, empty, escape as e } from './ui.js';
import { can } from './platform.js';
export function reviewWorkflow(c) {
    const w = workflows(c.data), reviewer = can(c.scope, 'review');
    if (c.screen.id === 'REV-01') {
        const s = c.data.sessions.find(s => s.id === c.params.sessionId);
        if (!s)
            return empty('Debrief unavailable', 'No assigned session.');
        const x = w.exercises[s.id], completed = ['ended', 'review', 'archived'].includes(s.status);
        return heading('Exercise debrief', `${s.title} · ${s.status}`, reviewer ? link('Review findings', href(c, 'REV-02'), 'primary') : '') + notice(completed ? 'Human review in progress' : 'Exercise has not completed', completed ? 'Draft observations remain separate from approved conclusions.' : 'Reflection and report composition open after the session ends.') + `<div class="grid two"><div class="stack">${form('reflection.save', s.id, undefined, `${field('reflection', reviewer ? 'Facilitator note' : 'Optional personal reflection', '', undefined, 'Attributed to your current fixture identity.', false, 'textarea')}`, 'Save reflection', !completed ? 'data-readonly="true"' : '')}${panel('Your reflections', body(x.reflections.filter(r => reviewer || r.subject === 'p-self').map(r => `<p>${e(r.text)}</p>`).join('') || '<p class="meta">No submitted reflections.</p>'))}</div><div class="stack">${panel('Reviewed findings', table(['Finding', 'State', ''], c.data.findings.filter(f => w.findings[f.id]?.sessionId === s.id && (reviewer || f.status === 'approved')).map(f => [e(f.title), statusBadge(f.status), link('Open', href(c, 'REV-03', { findingId: f.id }))]), 'Reviewed session observations'))}${reviewer && completed ? form('report.create', 'new', undefined, `${hiddenSession(s.id)}<h2>Compose a report from reviewed evidence</h2>${field('title', 'Report title', `${s.title} · after-action report`, undefined, '', true)}${field('reportType', 'Report type', 'After-action report', ['After-action report', 'Executive summary', 'Personal development report'], '', true)}`, 'Create report draft') : ''}</div></div>`;
    }
    if (c.screen.id === 'REV-02') {
        const status = value(c, 'status', 'All'), q = value(c, 'q').toLowerCase(), findings = c.data.findings.filter(f => (!c.params.sessionId || w.findings[f.id]?.sessionId === c.params.sessionId) && (status === 'All' || f.status === status) && f.title.toLowerCase().includes(q));
        return heading('Findings review', 'Inspect every citation and resolve attribution before approval.', link('Report library', href(c, 'REP-01'), 'secondary')) + `<form class="filters" data-filter-form>${field('q', 'Search findings', value(c, 'q'))}${field('status', 'Review state', status, ['All', 'draft', 'disputed', 'approved', 'corrected'])}<button type="submit" class="btn secondary">Apply</button></form>` + panel('Review queue', table(['Finding', 'Subject', 'Opportunity / level', 'Evidence inspection', 'State', ''], findings.map(f => [e(f.title), e(f.subject), `${e(f.opportunity)}<small>${typeof f.level === 'number' ? `Rubric ${f.level}` : e(f.level)}</small>`, `${w.findings[f.id].inspected.length} / ${f.evidence.length} inspected`, statusBadge(f.status), link('Review', href(c, 'REV-03', { findingId: f.id }))]), 'Findings review queue'));
    }
    const f = c.data.findings.find(f => f.id === c.params.findingId);
    if (!f)
        return empty('Finding unavailable', 'No authorized observation in this scope.');
    const state = w.findings[f.id], editable = reviewer;
    return heading(f.title, 'Evidence, attribution and correction history remain explicit.') + `<div class="review-strip">${statusBadge(f.status)} · revision ${f.version} · ${e(f.subject)}</div><div class="grid two"><div class="stack">${panel('Claim & attribution', body(`<p class="readable">${e(f.claim)}</p><dl class="detail-dl"><dt>Opportunity</dt><dd>${e(f.opportunity)}</dd><dt>Level</dt><dd>${typeof f.level === 'number' ? `${f.level} / 3` : e(f.level)}</dd><dt>Attribution</dt><dd>${e(f.attribution)}</dd><dt>Reviewer</dt><dd>${e(f.reviewer)}</dd></dl>`))}${panel('Cited evidence', body(f.evidence.length ? f.evidence.map(id => { const ev = c.data.evidence.find(e => e.id === id); return `<section class="citation"><h3>${e(ev?.title || 'Evidence unavailable')}</h3>${ev ? `<p class="meta">${e(ev.source)} · v${e(ev.version)}</p><pre class="evidence-content">${e(ev.content)}</pre>${editable ? action(state.inspected.includes(id) ? 'Inspected' : 'Mark inspected', 'finding.inspect', f.id, { evidence: id }, '', f.version) : ''}` : notice('Unavailable evidence', 'This observation cannot be approved until the missing reference is resolved.', 'warning')}</section>`; }).join('') : notice('No qualifying evidence', 'N/O and N/A remain distinct from numeric zero.', 'warning')))}${panel('Revision & correction history', table(['Version', 'State', 'Claim', 'Reason'], state.history.map(h => [String(h.version), statusBadge(h.state), e(h.claim), e(h.reason)]), 'Finding revisions'))}</div><div class="stack">${editable ? panel('Reviewer decision', body(`<div class="form-actions">${action('Approve inspected finding', 'finding.approve', f.id, {}, 'Approve this evidence and attribution?', f.version)}${button('Reject with reason', 'workflow-finding-reject', 'secondary', `data-id="${f.id}"`)}</div><p class="meta">Approval requires every citation to be inspected and available.</p>`)) : ''}${editable ? form('finding.amend', f.id, f.version, `<h2>Amend observation</h2>${field('claim', 'Claim', f.claim, undefined, 'Amendment resets inspection and approval.', true, 'textarea')}${field('attribution', 'Attribution', f.attribution, undefined, '', true, 'textarea')}${field('evidence', 'Evidence IDs', f.evidence.join(', '))}${field('level', 'Rubric level', String(f.level), ['0', '1', '2', '3', 'not_observed', 'not_applicable'], '', true)}${field('rationale', 'Amendment rationale', '', undefined, 'Dependent publications are flagged for amendment.', true, 'textarea')}`) : ''}${f.subject !== 'Team' && can(c.scope, 'profile', f.subject) ? form('finding.challenge', f.id, f.version, `${field('rationale', 'Challenge attribution', '', undefined, 'Explain the specific evidence or contribution issue.', true, 'textarea')}`, 'Submit challenge') : ''}${f.challenge ? panel('Participant correction', body(`<p>${e(f.challenge)}</p>${state.resolution ? `<p>${e(state.resolution)}</p>` : ''}`)) : ''}${editable && f.status === 'disputed' ? form('finding.resolve', f.id, f.version, `<h2>Resolve participant correction</h2>${field('outcome', 'Decision', 'accept', ['accept', 'reject'], '', true)}${field('claim', 'Corrected claim', f.claim, undefined, 'Required if accepted.', true, 'textarea')}${field('rationale', 'Review rationale', '', undefined, 'Original report snapshots remain unchanged.', true, 'textarea')}`, 'Resolve correction') : ''}${panel('Affected publications', body(c.data.reports.filter(r => r.findingIds.includes(f.id)).map(r => `<p>${link(r.title, href(c, 'REV-05', { reportId: r.id }))} · ${w.reports[r.id].needsAmendment.length ? 'Amendment required' : r.status}</p>`).join('') || '<p>No dependent reports.</p>'))}</div></div>`;
}
function hiddenSession(id) { return `<input type="hidden" name="session" value="${e(id)}">`; }
export function reportWorkflow(c) {
    const r = c.data.reports.find(r => r.id === c.params.reportId);
    if (!r)
        return empty('Report unavailable', 'No report is available for this audience.');
    const state = workflows(c.data).reports[r.id], reviewer = can(c.scope, 'review');
    if (c.screen.id === 'REV-04') {
        const immutable = ['published', 'superseded', 'withdrawn'].includes(r.status);
        const facts = c.data.findings.filter(f => f.status === 'approved' && (!state.sessionId || workflows(c.data).findings[f.id]?.sessionId === state.sessionId));
        return heading(r.title, `Report revision ${r.revision} · ${r.status}`, immutable ? action('Create amendment', 'report.amend', r.id, {}, 'Create a separate draft amendment while preserving this publication?', r.version) : '') + `<div class="grid two"><div class="stack">${form('report.save', r.id, r.version, `${field('title', 'Report title', r.title, undefined, '', true)}${field('summary', 'Executive summary', r.summary, undefined, 'Subsequent edits invalidate approval.', true, 'textarea')}${field('audience', 'Report audience', r.audience, ['Program members', 'Review team', 'Participant self'], 'Program reports cannot include private individual observations.', true)}${checks('findings', 'Reviewed findings to include', facts.map(f => ({ id: f.id, name: `${f.title} · ${f.subject}` })), r.findingIds)}<h3>Narrative sections</h3>${state.sections.map((s, i) => `<fieldset class="report-section-editor"><legend>Section ${i + 1}</legend><input type="hidden" name="section-id-${i}" value="${e(s.id)}">${field(`section-title-${i}`, 'Section title', s.title, undefined, '', true)}${field(`section-body-${i}`, 'Section text', s.body, undefined, '', true, 'textarea')}${field(`section-audience-${i}`, 'Section audience', s.audience, ['Program members', 'Review team', 'Participant self'], 'Exported bytes use the same audience projection.', true)}</fieldset>`).join('')}<input type="hidden" name="section-count" value="${state.sections.length}">`, 'Save draft', immutable ? 'data-readonly="true"' : '')}${!immutable ? button('Add narrative section', 'workflow-add-section', 'secondary', `data-id="${r.id}"`) : ''}</div><div class="stack">${panel('Approval checklist', body(`<dl class="detail-dl"><dt>Content / audience digest</dt><dd>${reportDigest(c.data, r.id)}</dd><dt>Approval</dt><dd>${state.approval ? `${e(state.approval.reviewer)} · ${state.approval.digest}` : 'Not approved'}</dd></dl>${r.findingIds.some(id => c.data.findings.find(f => f.id === id)?.status !== 'approved') ? notice('Unapproved finding included', 'Resolve or remove unsupported findings before approval.', 'warning') : notice('Reviewed evidence selected', 'Inspect narrative claims and limits before approving.')}<div class="form-actions">${!immutable ? action('Submit for review', 'report.submit', r.id, {}, '', r.version) : ''}${!immutable ? action('Approve exact content & audience', 'report.approve', r.id, { digest: reportDigest(c.data, r.id) }, 'Approve this report digest and audience?', r.version) : ''}${r.status === 'approved' ? action('Publish approved revision', 'report.publish', r.id, { digest: reportDigest(c.data, r.id) }, 'Publish this exact approved revision?', r.version) : ''}</div>`))}${state.amends ? notice('Amendment draft', `Supersedes ${state.amends} only after this new revision is approved and published.`) : ''}${state.needsAmendment.length ? notice('Corrections require amendment', state.needsAmendment.join('; '), 'warning') : ''}</div></div>`;
    }
    let snap;
    try {
        snap = permittedReport(c.data, r.id, c.scope, value(c, 'revision') || undefined);
    }
    catch (err) {
        return heading(r.title, r.status) + notice('Publication unavailable', err.message, 'warning') + (reviewer ? `${action('Create amendment', 'report.amend', r.id, {}, 'Create a new draft amendment?', r.version)}${link('Open editor', href(c, 'REV-04'), 'secondary')}` : '');
    }
    return heading('Published report', `${snap.revision} · ${snap.status}`, `${button('Export published snapshot', 'workflow-export-report', 'secondary', `data-id="${r.id}" data-revision="${e(snap.revision)}"`)}${reviewer ? action('Create amendment', 'report.amend', r.id, {}, 'Create a new draft amendment?', r.version) : ''}`) + (state.needsAmendment.length ? notice('Later correction recorded', 'This historical publication remains unchanged; a reviewed amendment is required.', 'warning') : '') + `<article class="report-document"><header class="document-header">${statusBadge(snap.status)}<h1>${e(snap.title)}</h1><p class="meta">Revision ${e(snap.revision)} · ${e(snap.audience)} · ${e(snap.reviewer)} · ${e(snap.date)}</p></header><nav aria-label="Report contents">${snap.sections.map(s => `<a href="#report-${e(s.id)}">${e(s.title)}</a>`).join(' · ')}</nav>${snap.sections.map(s => `<section id="report-${e(s.id)}"><h2>${e(s.title)}</h2><p class="readable">${e(s.body)}</p></section>`).join('')}<h2>Reviewed findings</h2>${snap.findings.map(f => `<section><h3>${e(f.title)}</h3><p>${e(f.claim)}</p>${f.evidence.map(ev => `<details><summary>${e(ev.title)} · ${e(ev.id)}</summary><pre class="evidence-content">${e(ev.content)}</pre></details>`).join('')}</section>`).join('')}<p class="meta">Synthetic exercise · publication digest ${e(snap.digest)}</p></article>` + panel('Publication history', table(['Revision', 'State', 'Reviewer', ''], state.history.map(s => [s.revision, statusBadge(s.status), e(s.reviewer), link('Read snapshot', href(c, 'REV-05', {}, { revision: s.revision }))]), 'Published revision history')) + (reviewer && r.status === 'published' ? button('Withdraw with rationale', 'workflow-report-withdraw', 'secondary', `data-id="${r.id}"`) : '');
}
